        crate::providers::normalize_settings(&mut normalized);
        let previous: Option<String> = self
            .db
            .query_row("SELECT value FROM kv WHERE key='settings'", [], |r| {
                r.get(0)
            })
            .optional()?;
        let previous = previous
            .map(|raw| serde_json::from_str::<Settings>(&raw))
            .transpose()?;
