) -> Value {
    let current = identity.map(|id| crate::agy_identity::matches(account, id));
    let note = match current {
        Some(true) => "已确认当前登录账户",
        Some(false) => "设备当前登录身份与此账户不一致；请在 agy 中切换后重新检查",
