fn bind_agy_identity(
    store: &Store,
    settings: &Settings,
    account: &Account,
    identity: &AccountIdentity,
) -> Result<Settings> {
    if !crate::agy_identity::matches(Some(account), identity) {
        return Ok(settings.clone());
    }
    let mut next = settings.clone();
    let a = next
        .accounts
        .iter_mut()
        .find(|a| key(a) == key(account))
        .context("账户已删除")?;
