pub fn location(source: &Source, settings: &Settings) -> local::Location {
    local::Location {
        path: home_path(&source.path),
        binary: source.codex_binary.clone(),
        proxy: if source.host_id.is_some() {
            source.proxy.clone().unwrap_or(ProxyConfig {
