    account: &Account,
    settings: &Settings,
    source_id: Option<&str>,
) -> Result<QuotaSnapshot> {
    let mut choices: Vec<_> = account
        .profile_refs()
        .into_iter()
        .filter_map(|r| source_for_profile(settings, r).ok())
        .map(|(s, p)| (s, Some(p)))
        .collect();
    choices.extend(
        settings
            .sources
            .iter()
            .filter(|s| {
                s.enabled
                    && s.provider == account.provider
                    && s.account_id == account.id
                    && s.codex_home_id.is_none()
