        if let Some(status) = child.try_wait()? {
            break status;
        }
        if start.elapsed() >= timeout {
            kill(&mut child);
            anyhow::bail!("查询超时");
        }
        std::thread::sleep(Duration::from_millis(25));
    };
    let output = match rx.recv_timeout(timeout.saturating_sub(start.elapsed())) {
        Ok(result) => result?,
        Err(_) => {
            kill(&mut child);
            anyhow::bail!("查询超时");
        }
    };
