        return aieyes_core::wakeups::runner::run(
            std::path::Path::new(root),
            args.get(i + 2).map(String::as_str),
        );
    }
    let root = args
        .windows(2)
        .find(|a| a[0] == "--data-dir")
        .map(|a| PathBuf::from(&a[1]))
        .or_else(|| std::env::var_os("AIEYES_DATA_DIR").map(PathBuf::from))
