    let lower = brand.to_ascii_lowercase();
    let Some(provider) = crate::contracts::PROVIDERS
        .iter()
        .find(|p| p.id == canonical(&lower) || p.name.to_lowercase() == lower)
    else {
        return name.into();
    };
    let normalized = provider.name;

    if suffix.is_empty() {
        normalized.into()
    } else {
        format!("{normalized} · {suffix}")
    }
